// The CLI verb parity check (the lead's acceptance for slice 7b): at D8 the `cerberus` on PATH
// becomes this build, so every command path and flag of main's CLI must exist here, or carry a
// decision below with an owner or an obsolete record, and a reason. testdata/clitree/main.tree is
// main's full cobra tree, generated by testdata/clitree/tree_gen_on_main.go.txt on a checkout of
// main. A new old verb, a verb dropped here, or a decision for something that is now present
// fails the test. docs/conversion-notes.md ("CLI verb parity") summarizes the table.

// Owners a decision may name. A slice owns a verb that returns with it; "$LEGACY until F" is the
// old binary, kept as $LEGACY through the cutover; obsolete and replaced need their evidence in
// the reason.
const (
	ownerSlice7c = "CW-20261115-0065" // slice 7c: the CLI follow-up over lanes this branch already serves
	ownerSlice9  = "slice 9"          // MCP
	ownerSlice10 = "slice 10"         // migrate-from, export-legacy
	ownerSlice11 = "slice 11"         // console
	ownerLegacy  = "slice 12; $LEGACY until F"
	obsolete     = "obsolete"
	replaced     = "replaced"
)

type parityDecision struct{ owner, reason string }

